-- public.institution_load_example: canonical source (STAB-1). Generated by scripts/fn-source.mjs from the database; edit THIS file and
-- ship the whole file in a new migration (node scripts/fn-source.mjs migration public.institution_load_example). No text patch.

-- public.institution_load_example(p_institution_id uuid, p_week_start date)
CREATE OR REPLACE FUNCTION public.institution_load_example(p_institution_id uuid, p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  inst public.institutions;
  s1 uuid; s2 uuid; f uuid; sp uuid; n uuid;
  d date;
  staff_ids uuid[];
  i int;
begin
  perform private.assert_access_open();  -- LEAVE1-3
  select * into inst from public.institutions where id = p_institution_id for update;
  if inst.id is null or not private.is_institution_member(inst.id, array['lead']) then
    return jsonb_build_object('result', 'rejected');
  end if;
  if not inst.simulation then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('not_simulation'));
  end if;
  if p_week_start is null or exists (select 1 from public.institution_stations where institution_id = inst.id)
     or exists (select 1 from public.institution_staff where institution_id = inst.id) then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('not_empty'));
  end if;
  insert into public.institution_stations (institution_id, name, sort) values (inst.id, 'Rhein 1', 0) returning id into s1;
  insert into public.institution_stations (institution_id, name, sort) values (inst.id, 'Rhein 2', 1) returning id into s2;
  -- Example times and classes of the synthetic test home (FE-123, «Beispielwert des Heims»; NAVORA sets no times).
  insert into public.institution_shift_types (institution_id, code, label, starts_at, ends_at, sort, shift_class) values
    (inst.id, 'F', 'Früh', '07:00', '15:30', 0, 'early') returning id into f;
  insert into public.institution_shift_types (institution_id, code, label, starts_at, ends_at, sort, shift_class) values
    (inst.id, 'S', 'Spät', '14:30', '23:00', 1, 'late') returning id into sp;
  insert into public.institution_shift_types (institution_id, code, label, starts_at, ends_at, sort, shift_class) values
    (inst.id, 'N', 'Nacht', '22:30', '07:15', 2, 'night') returning id into n;
  -- FE-123: test home 42 h per week at 100 % Pensum («Beispielwert des Heims»), only when the home has not entered one.
  update public.institutions set weekly_target_hours = coalesce(weekly_target_hours, 42) where id = inst.id;
  insert into public.institution_staffing_rules (institution_id, station_id, shift_type_id, required_total,
                                                 required_grade, required_grade_count, example) values
    (inst.id, s1, f, 2, 'nurse_hf_fh', 1, true), (inst.id, s1, sp, 2, 'nurse_hf_fh', 1, true),
    (inst.id, s1, n, 1, null, 0, true),
    (inst.id, s2, f, 3, 'nurse_hf_fh', 1, true), (inst.id, s2, sp, 2, 'nurse_hf_fh', 1, true),
    (inst.id, s2, n, 1, null, 0, true);
  with ins as (
    -- Pensum and shift model are synthetic example values (HD-3a), so the rule-based draft can plan the example.
    insert into public.institution_staff (institution_id, display_name, grade, home_station_id, pensum_pct, shift_model)
    select inst.id, v.name, v.grade, case when v.st = 1 then s1 else s2 end, v.pensum, v.model
    from (values ('Anna Muster', 'nurse_hf_fh', 2, 1, 100, 'any'), ('Ben Beispiel', 'fage_efz', 2, 2, 80, 'no_night'),
                 ('Carla Test', 'fage_efz', 2, 3, 100, 'any'), ('David Probe', 'ags_eba', 2, 4, 60, 'late_only'),
                 ('Eva Fiktiv', 'nurse_hf_fh', 1, 5, 100, 'any'), ('Felix Demo', 'fage_efz', 1, 6, 80, 'early_only'),
                 ('Gina Simul', 'nurse_hf_fh', 2, 7, 90, 'no_night'), ('Hugo Platz', 'ags_eba', 1, 8, 100, 'any'))
         v(name, grade, st, ord, pensum, model)
    order by v.ord
    returning id, display_name)
  select array_agg(id order by display_name) into staff_ids from ins;
  -- staff_ids by name: 1 Anna(HF,R2) 2 Ben(FaGe,R2) 3 Carla(FaGe,R2) 4 David(AGS,R2) 5 Eva(HF,R1) 6 Felix(FaGe,R1)
  --                    7 Gina(HF,R2) 8 Hugo(AGS,R1)
  for i in 0..6 loop
    d := p_week_start + i;
    -- Rhein 2 Früh: Anna, Ben, Carla (Mon–Fri), weekend only two (a visible gap)
    insert into public.institution_assignments (institution_id, station_id, shift_type_id, work_date, staff_id)
      values (inst.id, s2, f, d, staff_ids[1]), (inst.id, s2, f, d, staff_ids[2]);
    if i < 5 then
      insert into public.institution_assignments (institution_id, station_id, shift_type_id, work_date, staff_id)
        values (inst.id, s2, f, d, staff_ids[3]);
    end if;
    -- Rhein 2 Spät: Gina, David
    insert into public.institution_assignments (institution_id, station_id, shift_type_id, work_date, staff_id)
      values (inst.id, s2, sp, d, staff_ids[7]), (inst.id, s2, sp, d, staff_ids[4]);
    -- Rhein 1 Früh: Eva, Felix; Rhein 1 Spät: Hugo only (gap, HF missing)
    insert into public.institution_assignments (institution_id, station_id, shift_type_id, work_date, staff_id)
      values (inst.id, s1, f, d, staff_ids[5]), (inst.id, s1, f, d, staff_ids[6]), (inst.id, s1, sp, d, staff_ids[8]);
  end loop;
  perform private.institution_audit(inst.id, 'institution_load_example', 'institutions', inst.id,
    jsonb_build_object('week_start', p_week_start));
  return jsonb_build_object('result', 'ok');
end $function$;

revoke all on function public.institution_load_example(p_institution_id uuid, p_week_start date) from public, anon, authenticated, service_role;
grant execute on function public.institution_load_example(p_institution_id uuid, p_week_start date) to authenticated;
grant execute on function public.institution_load_example(p_institution_id uuid, p_week_start date) to service_role;
